import java.util.*;

public class Main {
    public static void main(String[] args) {
        TenantScopedStore store = new TenantScopedStore();

        // Two different tenants store completely different data under the exact same key.
        store.put("store-A", "product-1", "Red Shoes, $50");
        store.put("store-B", "product-1", "Blue Shirt, $30");

        System.out.println("store-A's product-1: " + store.get("store-A", "product-1"));
        System.out.println("store-B's product-1: " + store.get("store-B", "product-1"));
        System.out.println("Isolation holds despite the identical key: " + !store.get("store-A", "product-1").equals(store.get("store-B", "product-1")));

        // Per-tenant rate limiting: tenant A's own bucket holds only 3 tokens.
        TenantRateLimiter limiter = new TenantRateLimiter(3);

        System.out.println("Tenant A request 1: " + limiter.allowRequest("store-A"));
        System.out.println("Tenant A request 2: " + limiter.allowRequest("store-A"));
        System.out.println("Tenant A request 3: " + limiter.allowRequest("store-A"));
        System.out.println("Tenant A request 4 (should be throttled, quota exhausted): " + limiter.allowRequest("store-A"));

        // Tenant B, a completely unrelated tenant, is entirely unaffected by A's exhausted quota.
        System.out.println("Tenant B request, despite A being throttled (should still succeed): " + limiter.allowRequest("store-B"));
    }
}

// A data store whose access is always scoped by tenant id, making two
// different tenants' identical keys fully independent of each other.
class TenantScopedStore {
    private final Map<String, Map<String, String>> dataByTenant = new HashMap<>(); // tenantId -> (key -> value)

    void put(String tenantId, String key, String value) {
        dataByTenant.computeIfAbsent(tenantId, id -> new HashMap<>()).put(key, value);
    }

    String get(String tenantId, String key) {
        Map<String, String> tenantData = dataByTenant.get(tenantId);
        return (tenantData != null) ? tenantData.get(key) : null; // can never see another tenant's data, even for the same key
    }
}

// Enforces an independent request quota per tenant, so one tenant's
// exhausted quota has zero effect on any other, unrelated tenant's own quota.
class TenantRateLimiter {
    private final int capacityPerTenant;
    private final Map<String, Integer> remainingByTenant = new HashMap<>(); // tenantId -> tokens remaining

    TenantRateLimiter(int capacityPerTenant) {
        this.capacityPerTenant = capacityPerTenant;
    }

    boolean allowRequest(String tenantId) {
        int remaining = remainingByTenant.getOrDefault(tenantId, capacityPerTenant); // each tenant starts with its own full quota
        if (remaining <= 0) {
            return false; // this tenant's own quota is exhausted
        }
        remainingByTenant.put(tenantId, remaining - 1);
        return true;
    }
}

