#include <iostream>
#include <map>
#include <string>
using namespace std;

// A data store whose access is always scoped by tenant id, making two
// different tenants' identical keys fully independent of each other.
class TenantScopedStore {
public:
    void put(const string& tenantId, const string& key, const string& value) {
        dataByTenant[tenantId][key] = value;
    }

    string get(const string& tenantId, const string& key) {
        auto tenantIt = dataByTenant.find(tenantId);
        if (tenantIt == dataByTenant.end()) return ""; // can never see another tenant's data, even for the same key
        auto keyIt = tenantIt->second.find(key);
        return (keyIt != tenantIt->second.end()) ? keyIt->second : "";
    }

private:
    map<string, map<string, string>> dataByTenant; // tenantId -> (key -> value)
};

// Enforces an independent request quota per tenant, so one tenant's
// exhausted quota has zero effect on any other, unrelated tenant's own quota.
class TenantRateLimiter {
public:
    TenantRateLimiter(int capacityPerTenant) : capacityPerTenant(capacityPerTenant) {}

    bool allowRequest(const string& tenantId) {
        if (remainingByTenant.find(tenantId) == remainingByTenant.end()) {
            remainingByTenant[tenantId] = capacityPerTenant; // each tenant starts with its own full quota
        }
        if (remainingByTenant[tenantId] <= 0) {
            return false; // this tenant's own quota is exhausted
        }
        remainingByTenant[tenantId]--;
        return true;
    }

private:
    int capacityPerTenant;
    map<string, int> remainingByTenant; // tenantId -> tokens remaining
};

int main() {
    TenantScopedStore store;

    // Two different tenants store completely different data under the exact same key.
    store.put("store-A", "product-1", "Red Shoes, $50");
    store.put("store-B", "product-1", "Blue Shirt, $30");

    cout << "store-A's product-1: " << store.get("store-A", "product-1") << endl;
    cout << "store-B's product-1: " << store.get("store-B", "product-1") << endl;
    cout << "Isolation holds despite the identical key: " << (store.get("store-A", "product-1") != store.get("store-B", "product-1") ? "true" : "false") << endl;

    // Per-tenant rate limiting: tenant A's own bucket holds only 3 tokens.
    TenantRateLimiter limiter(3);

    cout << "Tenant A request 1: " << (limiter.allowRequest("store-A") ? "true" : "false") << endl;
    cout << "Tenant A request 2: " << (limiter.allowRequest("store-A") ? "true" : "false") << endl;
    cout << "Tenant A request 3: " << (limiter.allowRequest("store-A") ? "true" : "false") << endl;
    cout << "Tenant A request 4 (should be throttled, quota exhausted): " << (limiter.allowRequest("store-A") ? "true" : "false") << endl;

    // Tenant B, a completely unrelated tenant, is entirely unaffected by A's exhausted quota.
    cout << "Tenant B request, despite A being throttled (should still succeed): " << (limiter.allowRequest("store-B") ? "true" : "false") << endl;

    return 0;
}

